import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int N = Integer.parseInt(st.nextToken());
        int K = Integer.parseInt(st.nextToken());
        long T = Long.parseLong(st.nextToken());

        int[] P = new int[N + 1];
        st = new StringTokenizer(br.readLine());
        int total = 0;
        for (int i = 1; i <= N; i++) {
            P[i] = Integer.parseInt(st.nextToken());
            total += P[i];
        }

        int[] s = new int[K + 1];
        st = new StringTokenizer(br.readLine());
        int idx = 0;
        for (int i = 1; i <= N; i++) {
            int g = Integer.parseInt(st.nextToken());
            if (g == 1) {
                s[++idx] = i;
            }
        }

        final int INF = 1_000_000_000;
        int[][] dp = new int[K + 1][total + 1];
        for (int i = 0; i <= K; i++) {
            Arrays.fill(dp[i], INF);
        }
        dp[0][0] = 0;

        int maxScoreSoFar = 0;

        for (int pos = 1; pos <= N; pos++) {
            int p = P[pos];
            int maxJ = Math.min(pos, K);

            for (int j = maxJ; j >= 1; j--) {
                int cost = Math.abs(s[j] - pos);
                int[] prev = dp[j - 1];
                int[] cur = dp[j];

                int maxSc = maxScoreSoFar;
                int lim = 9 * (j - 1);
                if (maxSc > lim) maxSc = lim;

                for (int sc = 0; sc <= maxSc; sc++) {
                    int val = prev[sc];
                    if (val != INF) {
                        int nc = val + cost;
                        int ns = sc + p;
                        if (nc < cur[ns]) {
                            cur[ns] = nc;
                        }
                    }
                }
            }

            maxScoreSoFar += p;
        }

        int answer = 0;
        for (int sc = total; sc >= 0; sc--) {
            if (dp[K][sc] <= T) {
                answer = sc;
                break;
            }
        }

        System.out.println(answer);
    }
}
