        BufferedReader br;
        StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        int K = fs.nextInt();
        int T = fs.nextInt();

        int[] P = new int[N + 1];
        for (int i = 1; i <= N; i++) {
            P[i] = fs.nextInt();
        }

        int[] a = new int[K + 1];
        int idx = 0;
        for (int i = 1; i <= N; i++) {
            int g = fs.nextInt();
            if (g == 1) {
                a[++idx] = i;
            }
        }

        int Vmax = 9 * K;
        int INF = T + 1;

        int[][] dp = new int[K + 1][Vmax + 1];
        for (int i = 0; i <= K; i++) {
            Arrays.fill(dp[i], INF);
        }
        dp[0][0] = 0;

        int[] maxV = new int[K + 1];
        Arrays.fill(maxV, -1);
        maxV[0] = 0;

        for (int i = 1; i <= N; i++) {
            int p = P[i];
            int maxJ = Math.min(i, K);

            for (int j = maxJ; j >= 1; j--) {
                int srcMax = maxV[j - 1];
                if (srcMax < 0) continue;

                int cost = a[j] - i;
                if (cost < 0) cost = -cost;

                int limit = srcMax;
                int maxAdd = Vmax - p;
                if (limit > maxAdd) limit = maxAdd;

                int[] prev = dp[j - 1];
                int[] curr = dp[j];
                int maxNew = -1;

                for (int v = 0; v <= limit; v++) {
                    int c = prev[v];
                    if (c != INF) {
                        int nc = c + cost;
                        if (nc <= T) {
                            int nv = v + p;
                            if (nc < curr[nv]) {
