                            }
                            if (nv > maxNew) {
                                maxNew = nv;
                            }
                        }
                    }
                }

                if (maxNew > maxV[j]) {
                    maxV[j] = maxNew;
                }
            }
        }

        int ans = 0;
        for (int v = Vmax; v >= 0; v--) {
            if (dp[K][v] <= T) {
                ans = v;
                break;
            }
        }

        System.out.println(ans);
    }
